sys_variable_value.value:
(function execute(inputs, outputs) {
    var threshold = inputs.cpu_thresh || 5;
    var factor = parseFloat(inputs.carbon_factor) || 0.85;
    
    var totalWatts = 0;
    var serverCount = 0;
    
    // Query CMDB for active servers with CPU > 0 and <= threshold
    var grServer = new GlideRecord('cmdb_ci_server');
    grServer.addQuery('install_status', 1); // In Use
    grServer.addQuery('x_snc_enterprise_0_cpu_utilization', '>', 0);
    grServer.addQuery('x_snc_enterprise_0_cpu_utilization', '<=', threshold);
    grServer.query();
    
    while (grServer.next()) {
        serverCount++;
        // Stripped leading spaces from field name
        var serverWatts = grServer.getValue('x_snc_enterprise_0_power_wattage') 
            ? parseFloat(grServer.getValue('x_snc_enterprise_0_power_wattage')) 
            : 400;
        totalWatts += serverWatts;
    }
    
    // Convert Watts to Monthly kWh and apply carbon factor
    var monthlyKWh = (totalWatts / 1000) * 24 * 30;
    
    outputs.total_co2e_lbs = monthlyKWh * factor;
    outputs.server_count = serverCount;
})(inputs, outputs);

